// Generated by agenticspec ui generate. Never edit: change the document and generate again.
//
// The runtime every generated page calls, the same bytes for every document: the hash router,
// page and shell state, the navigation, the lifecycle of a read (idle, loading, ready, empty,
// failed) and its live updates, the scope of a widget, commands and forms, toasts, and the
// command hooks of the host.

import {
  computed,
  inject,
  onBeforeUnmount,
  onMounted,
  reactive,
  ref,
  watch,
  type App as VueApp,
  type Component,
  type InjectionKey,
  type Ref,
} from 'vue';
import { createClient, type ChannelName, type Client, type Commands, type Reads, type Row, type Value } from './client';

export type ReadName = keyof Reads;
export type CommandName = keyof Commands;
export type Scalar = string | number | boolean | null;
export type SectionState = 'idle' | 'loading' | 'ready' | 'empty' | 'failed';
export type Tone = 'neutral' | 'info' | 'success' | 'warning' | 'danger';

export interface RouteDef {
  name: string;
  segments: string[];
  params: string[];
  component: Component;
}

export interface Toast {
  id: number;
  tone: Tone;
  text: string;
}

/** What a command hook of the host may do after a command was answered. */
export interface HookContext {
  navigate(page: string, params?: Record<string, unknown>): void;
  toast(tone: Tone, text: string): void;
}

/** A hook of the host, run when a command was carried out (not when it was refused). */
export type CommandHook = (answer: Row | null, ctx: HookContext) => void;
export type CommandHooks = { [C in CommandName]?: CommandHook };

export interface StateDef {
  store: 'memory' | 'url' | 'local_storage';
  initial: Scalar;
}

export interface ThemeDef {
  initial: string;
  themes: string[];
  state: string | null;
}

/** One section of the navigation and its pages. */
export interface NavDef {
  label: string;
  pages: { name: string; label: string }[];
}

export interface InstallOptions {
  app: string;
  title: string;
  home: string;
  routes: RouteDef[];
  client: Client;
  hosts: Record<string, Component>;
  hooks: CommandHooks;
  shell: Record<string, StateDef>;
  theme: ThemeDef | null;
  nav?: NavDef[];
}

interface Route {
  name: string;
  params: Record<string, string>;
  query: Record<string, string>;
}

interface Runtime {
  options: InstallOptions;
  route: Route;
  refresh: Ref<number>;
  toasts: Toast[];
  shell: Record<string, Scalar>;
  /** The reader's system theme, which a document that names no theme follows. */
  system: Ref<string>;
  /** The client of each scope and source a widget read, so widgets of one scope share it. */
  scopes: Map<string, Client>;
}

const KEY: InjectionKey<Runtime> = Symbol('agenticspec-ui');

function useRuntime(): Runtime {
  const rt = inject(KEY);
  if (!rt) throw new Error('the generated app is not installed');
  return rt;
}

// ------------------------------------------------------------------------------------------
// Router: `#/<segments>/<params>?<query>`.

function parseHash(hash: string, routes: RouteDef[], home: string): Route {
  const raw = hash.replace(/^#\/?/, '');
  const [path, search = ''] = raw.split('?');
  const parts = path ? path.split('/').map((p) => decodeURIComponent(p)) : [];
  const query: Record<string, string> = {};
  for (const [k, v] of new URLSearchParams(search)) query[k] = v;
  for (const r of routes) {
    if (parts.length !== r.segments.length + r.params.length) continue;
    if (!r.segments.every((s, i) => parts[i] === s)) continue;
    const params: Record<string, string> = {};
    r.params.forEach((p, i) => {
      params[p] = parts[r.segments.length + i];
    });
    return { name: r.name, params, query };
  }
  return { name: home, params: {}, query };
}

function hrefOf(routes: RouteDef[], name: string, params: Record<string, unknown> = {}): string {
  const r = routes.find((x) => x.name === name);
  if (!r) return '#/';
  const parts = [...r.segments, ...r.params.map((p) => encodeURIComponent(String(params[p] ?? '')))];
  return '#/' + parts.join('/');
}

export function useRouter() {
  const rt = useRuntime();
  return {
    href: (name: string, params: Record<string, unknown> = {}) => hrefOf(rt.options.routes, name, params),
    go: (name: string, params: Record<string, unknown> = {}) => {
      location.hash = hrefOf(rt.options.routes, name, params);
    },
  };
}

function storageKey(app: string, name: string): string {
  return `${app}.${name}`;
}

function readStored(app: string, name: string): Scalar | undefined {
  try {
    const v = localStorage.getItem(storageKey(app, name));
    return v === null ? undefined : (JSON.parse(v) as Scalar);
  } catch {
    return undefined;
  }
}

function writeStored(app: string, name: string, v: Scalar): void {
  try {
    localStorage.setItem(storageKey(app, name), JSON.stringify(v));
  } catch {
    // A browser without storage keeps the value for the tab.
  }
}

function writeQuery(name: string, value: Scalar): void {
  const [path, search = ''] = location.hash.replace(/^#/, '').split('?');
  const q = new URLSearchParams(search);
  if (value === null || value === '' || value === false) q.delete(name);
  else q.set(name, String(value));
  const s = q.toString();
  history.replaceState(null, '', `#${path || '/'}${s ? '?' + s : ''}`);
}

export function install(app: VueApp, options: InstallOptions): void {
  const shell: Record<string, Scalar> = reactive({});
  for (const [name, def] of Object.entries(options.shell)) {
    shell[name] = def.store === 'local_storage' ? (readStored(options.app, name) ?? def.initial) : def.initial;
  }
  if (options.theme?.state && !options.theme.themes.includes(String(shell[options.theme.state]))) {
    shell[options.theme.state] = options.theme.initial;
  }
  const dark = typeof matchMedia === 'function' ? matchMedia('(prefers-color-scheme: dark)') : null;
  const rt: Runtime = {
    options,
    route: reactive(parseHash(location.hash, options.routes, options.home)),
    refresh: ref(0),
    toasts: reactive([]),
    shell,
    system: ref(dark?.matches ? 'dark' : 'light'),
    scopes: new Map(),
  };
  dark?.addEventListener?.('change', (e) => {
    rt.system.value = e.matches ? 'dark' : 'light';
  });
  window.addEventListener('hashchange', () => {
    Object.assign(rt.route, parseHash(location.hash, options.routes, options.home));
  });
  watch(
    () => ({ ...shell }),
    (now) => {
      for (const [name, def] of Object.entries(options.shell)) {
        if (def.store === 'local_storage') writeStored(options.app, name, now[name]);
      }
    },
  );
  document.title = options.title;
  app.provide(KEY, rt);
}

let toastSeq = 0;

function pushToast(rt: Runtime, tone: Tone, text: string): void {
  const id = ++toastSeq;
  rt.toasts.push({ id, tone, text });
  setTimeout(() => dismissToast(rt, id), 8000);
}

function dismissToast(rt: Runtime, id: number): void {
  const i = rt.toasts.findIndex((t) => t.id === id);
  if (i >= 0) rt.toasts.splice(i, 1);
}

/** The page the route names, for App.vue. */
export function useApp() {
  const rt = useRuntime();
  onMounted(() => {
    document.body.dataset.ready = 'true';
  });
  return reactive({
    page: computed(() => (rt.options.routes.find((r) => r.name === rt.route.name) ?? rt.options.routes[0]).component),
    pageKey: computed(() => rt.route.name + '/' + JSON.stringify(rt.route.params)),
  });
}

/**
 * The shell: the app's title, its state, the theme (the system's when the document names none),
 * the navigation with the page the route names, and the toasts.
 */
export function useShell() {
  const rt = useRuntime();
  const theme = rt.options.theme;
  return reactive({
    title: rt.options.title,
    state: rt.shell,
    theme: computed(() => (theme?.state ? String(rt.shell[theme.state]) : (theme?.initial ?? rt.system.value))),
    themes: theme?.state ? theme.themes : [],
    nav: computed(() =>
      (rt.options.nav ?? []).map((s) => ({
        label: s.label,
        items: s.pages.map((p) => ({
          label: p.label,
          href: hrefOf(rt.options.routes, p.name),
          current: p.name === rt.route.name,
        })),
      })),
    ),
    toasts: rt.toasts,
    setTheme: (t: string) => {
      if (theme?.state) rt.shell[theme.state] = t;
    },
    dismiss: (id: number) => dismissToast(rt, id),
  });
}

export function useHosts(): Record<string, Component> {
  return useRuntime().options.hosts;
}

/** A page: its path parameters and its state, kept where each state's store says. */
export function usePage(def: { params: string[]; state: Record<string, StateDef> }) {
  const rt = useRuntime();
  const params: Record<string, string> = {};
  for (const p of def.params) params[p] = rt.route.params[p] ?? '';
  const state: Record<string, Scalar> = reactive({});
  for (const [name, d] of Object.entries(def.state)) {
    if (d.store === 'url') state[name] = rt.route.query[name] ?? d.initial;
    else if (d.store === 'local_storage') state[name] = readStored(rt.options.app, name) ?? d.initial;
    else state[name] = d.initial;
  }
  for (const [name, d] of Object.entries(def.state)) {
    if (d.store === 'memory') continue;
    watch(
      () => state[name],
      (v) => (d.store === 'url' ? writeQuery(name, v) : writeStored(rt.options.app, name, v)),
    );
  }
  return { params, state };
}

function empty(v: unknown): boolean {
  return v === '' || v === null || v === undefined;
}

function messageOf(e: unknown): string {
  if (e instanceof Error) return e.message;
  return String(e);
}

export interface ReadState<V extends ReadName> {
  state: SectionState;
  rows: Reads[V]['row'][];
  row: Reads[V]['row'] | null;
  error: string;
  reload(): void;
}

/**
 * How a read takes the events of its channel (only those of `on`, all when it is empty):
 * `refetch` reads again, once per `coalesce` milliseconds however many events came in them;
 * `insert_or_patch` gives the event's fields to the row whose `match` field equals the event's,
 * or puts the event first as a new row.
 */
export interface LiveDef {
  channel: string;
  on: string[];
  effect?: 'refetch' | 'insert_or_patch';
  match?: string;
  /** `params`: an event that carries a field of a read parameter with another value is dropped. */
  onlyIf?: 'params';
  coalesce?: number;
}

function outside(params: Record<string, Value>, data: Value): boolean {
  if (data === null || typeof data !== 'object' || Array.isArray(data)) return false;
  return Object.entries(params).some(([k, v]) => k in data && !empty(v) && data[k] !== v);
}

type Listener = (event: string, data: Value) => void;

// One subscription per client, channel and parameters, shared by every read that takes it.
const feeds = new WeakMap<Client, Map<string, { listeners: Set<Listener>; stop: () => void }>>();

function listen(client: Client, channel: string, params: Record<string, Value>, fn: Listener): () => void {
  let byKey = feeds.get(client);
  if (!byKey) {
    byKey = new Map();
    feeds.set(client, byKey);
  }
  const key = channel + '?' + JSON.stringify(params);
  let feed = byKey.get(key);
  if (!feed) {
    const listeners = new Set<Listener>();
    const stop = client.subscribe(channel as ChannelName, params, (event, data) => {
      for (const l of [...listeners]) l(event, data);
    });
    feed = { listeners, stop };
    byKey.set(key, feed);
  }
  const mine = feed;
  mine.listeners.add(fn);
  return () => {
    mine.listeners.delete(fn);
    if (mine.listeners.size === 0) {
      mine.stop();
      byKey.delete(key);
    }
  };
}

/** The scope parameters of a widget (D7 of the view layer). */
export interface WidgetScope {
  source?: string;
  architecture?: string;
  part?: string;
  instance?: number;
}

/**
 * The client a widget reads through: the adapter at `source`, which answers the scope; else the
 * app's own under `/scopes/<architecture>[/<part>[/<instance>]]`; else the app's own. Widgets of
 * one scope share one client, so they share its channels and its action set.
 */
export function useWidget(scope: WidgetScope): Client {
  const rt = useRuntime();
  if (!scope.source && !scope.architecture) return rt.options.client;
  const parts = [scope.architecture, scope.part, scope.instance].filter((p) => !empty(p)).map((p) => encodeURIComponent(String(p)));
  const key = scope.source ? 'source ' + scope.source.replace(/\/+$/, '') : '/scopes/' + parts.join('/');
  let client = rt.scopes.get(key);
  if (!client) {
    client = scope.source ? createClient(scope.source.replace(/\/+$/, '')) : rt.options.client.scope(key);
    rt.scopes.set(key, client);
  }
  return client;
}

/** What the action set (R5) of a scope allows. */
export interface ActionSet {
  /** `loading` until the source answered; `absent` when it has no action set or failed. */
  readonly state: 'loading' | 'ready' | 'absent';
  allows(command: string): boolean;
}

const actionSets = new WeakMap<Client, ActionSet>();

/**
 * The action set of a client's scope, read once per client: an action that sends a command shows
 * only when the set allows the command. While it loads no such action shows; a source without
 * an action set (404), or one that fails, shows every action, and the command (R4) refuses what
 * the principal may not do. Hiding is a convenience, not authorization.
 */
export function useActions(over?: Client): ActionSet {
  const rt = useRuntime();
  const client = over ?? rt.options.client;
  const known = actionSets.get(client);
  if (known) return known;
  const s = reactive({ state: 'loading' as ActionSet['state'], allowed: [] as string[] });
  const set: ActionSet = {
    get state() {
      return s.state;
    },
    allows: (command) => s.state === 'absent' || (s.state === 'ready' && s.allowed.includes(command)),
  };
  actionSets.set(client, set);
  client.actions().then(
    (list) => {
      if (list === null) {
        s.state = 'absent';
      } else {
        s.allowed = list.filter((e) => e.allowed).map((e) => e.command);
        s.state = 'ready';
      }
    },
    () => {
      s.state = 'absent';
    },
  );
  return set;
}

/**
 * A read: idle while a parameter is empty, loading, then ready or empty, or failed. It reads again
 * when its parameters change, after every command the page sends, and on the events of its live
 * channel as `LiveDef` says. A widget hands it the client of its scope.
 */
export function useRead<V extends ReadName>(
  view: V,
  params: () => Reads[V]['params'],
  live?: LiveDef,
  over?: Client,
): ReadState<V> {
  const rt = useRuntime();
  const client = over ?? rt.options.client;
  let seq = 0;
  // Typed as the state it is: reactive() would unwrap the row types into ones no row fits.
  const s = reactive({
    state: 'idle' as SectionState,
    rows: [] as Row[],
    row: null as Row | null,
    error: '',
    reload: () => void load(),
  }) as unknown as ReadState<V>;
  async function load(): Promise<void> {
    const p = params() as Record<string, Value>;
    if (Object.values(p).some(empty)) {
      seq++;
      s.state = 'idle';
      s.rows = [];
      s.row = null;
      return;
    }
    const mine = ++seq;
    if (s.state !== 'ready' && s.state !== 'empty') s.state = 'loading';
    try {
      const rows = (await client.read(view, params())) as Reads[V]['row'][];
      if (mine !== seq) return;
      s.rows = rows;
      s.row = rows[0] ?? null;
      s.state = rows.length ? 'ready' : 'empty';
      s.error = '';
    } catch (e) {
      if (mine !== seq) return;
      s.state = 'failed';
      s.error = messageOf(e);
    }
  }
  watch([() => JSON.stringify(params()), () => rt.refresh.value], () => void load(), { immediate: true });
  if (live) {
    let timer: ReturnType<typeof setTimeout> | null = null;
    const stop = listen(client, live.channel, params() as Record<string, Value>, (event, data) => {
      if (live.on.length > 0 && !live.on.includes(event)) return;
      if (live.onlyIf === 'params' && outside(params() as Record<string, Value>, data)) return;
      if (live.effect === 'insert_or_patch') {
        patch(s as unknown as { rows: Row[]; row: Row | null; state: SectionState }, live.match ?? 'id', data);
      } else if (!live.coalesce) {
        void load();
      } else if (timer === null) {
        timer = setTimeout(() => {
          timer = null;
          void load();
        }, live.coalesce);
      }
    });
    onBeforeUnmount(() => {
      if (timer !== null) clearTimeout(timer);
      stop();
    });
  }
  return s;
}

/** Gives an event's fields to the row it matches, or puts it first as a new row. */
function patch(s: { rows: Row[]; row: Row | null; state: SectionState }, match: string, data: Value): void {
  if (s.state === 'idle' || data === null || typeof data !== 'object' || Array.isArray(data)) return;
  const id = data[match];
  if (empty(id)) return;
  const i = s.rows.findIndex((r) => r[match] === id);
  if (i >= 0) s.rows.splice(i, 1, { ...s.rows[i], ...data });
  else s.rows.unshift({ ...data });
  s.row = s.rows[0] ?? null;
  if (s.state === 'empty') s.state = 'ready';
}

function hookContext(rt: Runtime): HookContext {
  return {
    navigate: (page, params = {}) => {
      location.hash = hrefOf(rt.options.routes, page, params);
    },
    toast: (tone, text) => pushToast(rt, tone, text),
  };
}

async function send<C extends CommandName>(
  rt: Runtime,
  name: C,
  input: Commands[C]['input'],
  done: (row: Row | null, ok: boolean) => void,
  client: Client = rt.options.client,
): Promise<void> {
  try {
    const answer = await client.command(name, input);
    done(answer.row, answer.ok);
    rt.refresh.value++;
    if (answer.ok) rt.options.hooks[name]?.(answer.row, hookContext(rt));
  } catch (e) {
    pushToast(rt, 'danger', messageOf(e));
  }
}

/** A command an action sends, its input bound from state or a row; a widget's goes to its scope. */
export function useCommand<C extends CommandName>(name: C, input: () => Commands[C]['input'], client?: Client) {
  const rt = useRuntime();
  const c = reactive({
    busy: false,
    answer: null as Row | null,
    refused: false,
    blocked: computed(() => Object.values(input() as Record<string, unknown>).some(empty)),
  });
  /** Sends the command; a row action hands the input its row binds. */
  async function run(over?: Commands[C]['input']): Promise<void> {
    c.busy = true;
    await send(
      rt,
      name,
      over ?? input(),
      (row, ok) => {
        c.answer = row;
        c.refused = !ok;
      },
      client,
    );
    c.busy = false;
  }
  return Object.assign(c, { run });
}

/** A form: its draft, sent with the page's path parameters; the answer is its result. */
export function useForm<C extends CommandName>(
  name: C,
  initial: Record<string, Scalar>,
  context: () => Record<string, Scalar>,
) {
  const rt = useRuntime();
  const f = reactive({
    draft: { ...initial } as Record<string, Scalar>,
    busy: false,
    answer: null as Row | null,
    refused: false,
  });
  async function submit(): Promise<void> {
    f.busy = true;
    await send(rt, name, { ...context(), ...f.draft } as unknown as Commands[C]['input'], (row, ok) => {
      f.answer = row;
      f.refused = !ok;
    });
    f.busy = false;
  }
  return Object.assign(f, { submit });
}

// ------------------------------------------------------------------------------------------
// Helpers the templates call.

/** `a contains b`: every word of b is in a, in any case; every row while b has none. */
export function contains(a: unknown, b: unknown): boolean {
  const words = String(b ?? '').toLowerCase().split(/\s+/).filter(Boolean);
  const text = String(a ?? '').toLowerCase();
  return words.every((w) => text.includes(w));
}

function scalar(v: unknown): Scalar {
  if (v === null || v === undefined) return null;
  if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') return v;
  return JSON.stringify(v);
}

/** The options of a choice read from rows: each row's value field and the field it shows. */
export function options(rows: Record<string, unknown>[], value: string, label: string) {
  return rows
    .filter((r) => !empty(r[value]))
    .map((r) => ({ value: scalar(r[value]), label: String(r[label] ?? r[value]) }));
}

export function text(v: unknown): string {
  return v === null || v === undefined ? '' : String(v);
}

export function flag(v: unknown): boolean {
  return v === true || v === 'true';
}
